css:
@page {
	size: A4 landscape;
	margin: 0;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
}

/* container ของแต่ละหน้า A4 landscape ที่บรรจุ 2 ใบ */
.page.wht-a4-landscape-page {
	width: 297mm;
	height: 210mm;
	display: flex;
	flex-direction: row;
	page-break-after: always;
	page-break-inside: avoid;
	overflow: hidden;
}

.page.wht-a4-landscape-page:last-child {
	page-break-after: auto;
}

/* กล่องครอบแต่ละใบ (ครึ่งหนึ่งของ A4 landscape) */
.wht-slot {
	width: 148.5mm;
	height: 210mm;
	position: relative;
	overflow: hidden;
}

/* ใบเอกสารเดิมขนาด A4 portrait → ย่อด้วย scale */
/* scale factor = 210/297 ≈ 0.7071 เพื่อให้สูง 297mm ย่อลงเหลือ 210mm */
.report-withholding-tax-cert {
	background-image: url("/assets/erpnext_thailand/images/wht/WithholdingTaxCert.png");
	background-size: 210mm 297mm;
	background-repeat: no-repeat;
	width: 210mm;
	height: 297mm;
	position: relative;
	transform: scale(0.7071);
	transform-origin: top left;
}

